**For example:**

| Test | Result |
| :--- | :--- |
| `BinaryTree<int, int> binaryTree; binaryTree.addNode("", 2, 4); cout << binaryTree.sumOfLeaves();` | 4 |
| `BinaryTree<int, int> binaryTree; binaryTree.addNode("", 2, 4); binaryTree.addNode("L", 3, 6); binaryTree.addNode("R", 5, 9); cout << binaryTree.sumOfLeaves();` | 15 |

Đáp án: ```cpp
void leafSum(Node *root, int& sum){
    if (!root)
        return;

    // add root value to sum if
    // root is a leaf node
    if (!root->pLeft && !root->pRight)
        sum += root->value;

    // propagate recursively in pLeft
    // and pRight subtree
    leafSum(root->pLeft, sum);
    leafSum(root->pRight, sum);
}
int sumOfLeaves(){
    int s = 0;
    leafSum(root,s);
    return s;

}
