  '454b8588-d18c-5b11-abc9-80732193b9b8', 'a18d481c-734f-54d5-9ed5-4cf1a3674707',
  'Class `ETNode` is used to store a node in expression tree, described as follows:

```cpp
class ETNode {
public:
    char val;
    ETNode *left;
    ETNode *right;
    ETNode() {
        this->left = this->right = NULL;
    };
    ETNode(char val) {
        this->val = val;
        this->left = this->right = nullptr;
    }
    ETNode(char val, ETNode* left, ETNode* right) {
        this->val = val;
        this->left = left;
        this->right = right;
    }
};
```

Where `val` is the value of the node (either an operand (`''0''-''9''`) or an operator (`+`, `-`, `*`)), and `left` and `right` are pointers to the left and right nodes, respectively.

**Request:** Implement the function:

```cpp
ETNode* constructET(string s);
```

where `s` is the postorder traversal of an expression tree. The length of the string is between 1 and 100000. This function returns the root of the expression tree constructed from the given postorder traversal.

**More information:**

- You can click [here](https://en.wikipedia.org/wiki/Expression_tree) for more information about expression trees.

**Example:**

The expression tree constructed with postorder `"55+8+42-*"` should be the tree shown in the image.

(Note: The image shows a tree with root `*`, left child `+`, and right child `-`. The left `+` has children `8` and `+`. The inner `+` has children `5` and `5`. The right `-` has children `4` and `2`.)

Note: In this exercise, the libraries `iostream`, `stack`, `queue`, `vector` and `using namespace std` are used. You can write helper functions; however, you are not allowed to use other libraries.

For example:

| Test | Result |
| :--- | :--- |
| | |

Đáp án: ```cpp
ETNode* constructET(string s) {
    int i = 0;
    ETNode* tree = NULL;
    stack<ETNode*> st;
    ETNode* temp_tree1;
    ETNode* temp_tree2;
    while (s[i] != ''\0'')
    {
        if (!(s[i] == ''+'' || s[i] == ''-'' || s[i] == ''*'' || s[i] == ''/''
        || s[i] == ''%'' || s[i] == ''^''))
        {
            ETNode* newNode = new ETNode(s[i]);
            tree = newNode;
            st.push(tree);
        }
        else
        {
            ETNode* newNode = new ETNode(s[i]);
            tree = newNode;
            temp_tree1 = st.top(); st.pop();
            temp_tree2 = st.top(); st.pop();
            tree->right = temp_tree1;
            tree->left = temp_tree2;
```', 4
);

