For example:

| Test | Result |
| :--- | :--- |
| | |

| Test | Result |
| :--- | :--- |
| BinarySearchTree<int> bst;\nbst.add(9);\nbst.add(2);\nbst.add(10);\nbst.deleteNode(9);\ncout << bst.inOrder(); | 2 10 |
| BinarySearchTree<int> bst;\nbst.add(9);\nbst.add(2);\nbst.add(10);\nbst.add(8);\ncout << bst.inOrder()<<endl;\nbst.add(11);\nbst.deleteNode(9);\ncout << bst.inOrder(); | 2 8 9 10\n2 8 10 11 |

Đáp án: ```cpp
Node* add_main (Node* root, T value)
{
    if (root == NULL)
    {
        Node* newNode = new Node(value);
        return newNode;
    }
    if (value > root->value)
    {
        root->pRight = add_main(root->pRight, value);
    }
    else root->pLeft = add_main(root->pLeft, value);
    return root;
}
void add(T value){
    root = add_main(root,value);
}
/* Given a non-empty binary search tree, return the node
with minimum value value found in that tree. Note that the
entire tree does not need to be searched. */
Node* minValueNode(Node* root)
{
    Node* current = root;
    
    /* loop down to find the leftmost leaf */
    while (current != NULL && current->pLeft != NULL)
        current = current->pLeft ;
    
    return current;
}
Node* delete_main(Node* root, T value)
{
    // base case
    if (root == NULL)
        return root;
    if (value < root->value)
        root->pLeft = delete_main(root->pLeft, value);
    else if (value > root->value)
        root->pRight = delete_main(root->pRight, value);
    else {
        if (root->pLeft==NULL and root->pRight==NULL)
            return NULL;
        else if (root->pLeft == NULL) {
            Node* temp = root->pRight;
            delete(root);
            return temp;
        }
        else if (root->pRight == NULL) {
            Node* temp= root->pLeft;
            delete(root);
            return temp;
        }

        // node with two children: Get the inorder successor
        // (smallest in the pRight subtree)
        Node* temp = minValueNode(root->pRight);

        // Copy the inorder successor''s content to this node
        root->value = temp->value;

        // Delete the inorder successor
        root->pRight = delete_main(root->pRight, temp->value);
    }
    return root;
}
void deleteNode(T value){
